function advanceToken(state) {
  if (state === null || typeof state !== 'object' || Array.isArray(state)) {
    throw new TypeError('state must be an object');
  }
  const { width, height, x, y, dx, dy } = state;
  if (!Number.isInteger(width) || width < 1 || width > 10000 ||
      !Number.isInteger(height) || height < 1 || height > 10000 ||
      !Number.isInteger(x) || x < 0 || x >= width ||
      !Number.isInteger(y) || y < 0 || y >= height ||
      ![-1, 0, 1].includes(dx) || ![-1, 0, 1].includes(dy)) {
    throw new TypeError('invalid state');
  }

  function step(position, velocity, length) {
    if (length === 1) return [0, 0];
    let next = position + velocity;
    let nextVelocity = velocity;
    if (next < 0 || next >= length) {
      nextVelocity = velocity;
      next = position + nextVelocity;
    }
    return [next, nextVelocity];
  }

  const [nextX, nextDx] = step(x, dx, width);
  const [nextY, nextDy] = step(y, dy, height);
  return { width, height, x: nextX, y: nextY, dx: nextDx, dy: nextDy };
}

module.exports = { advanceToken };

