'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['advanceToken']);
const { advanceToken } = api;

assert.deepStrictEqual(
  advanceToken({ width: 5, height: 4, x: 2, y: 2, dx: 1, dy: -1 }),
  { width: 5, height: 4, x: 3, y: 1, dx: 1, dy: -1 }
);
assert.deepStrictEqual(
  advanceToken({ width: 4, height: 3, x: 0, y: 2, dx: -1, dy: 1, extra: 'ignored' }),
  { width: 4, height: 3, x: 1, y: 1, dx: 1, dy: -1 }
);
assert.deepStrictEqual(
  advanceToken({ width: 3, height: 3, x: 2, y: 0, dx: 1, dy: -1 }),
  { width: 3, height: 3, x: 1, y: 1, dx: -1, dy: 1 }
);
assert.deepStrictEqual(
  advanceToken({ width: 3, height: 3, x: 1, y: 1, dx: 0, dy: 0 }),
  { width: 3, height: 3, x: 1, y: 1, dx: 0, dy: 0 }
);
assert.deepStrictEqual(
  advanceToken({ width: 1, height: 1, x: 0, y: 0, dx: -1, dy: 1 }),
  { width: 1, height: 1, x: 0, y: 0, dx: 0, dy: 0 }
);
assert.deepStrictEqual(
  advanceToken({ width: 1, height: 4, x: 0, y: 1, dx: 1, dy: 1 }),
  { width: 1, height: 4, x: 0, y: 2, dx: 0, dy: 1 }
);

const state = { width: 10000, height: 10000, x: 9999, y: 9999, dx: 0, dy: 0 };
const copy = { ...state };
const result = advanceToken(state);
assert.deepStrictEqual(state, copy);
assert.notStrictEqual(result, state);
assert.deepStrictEqual(Object.keys(result), ['width', 'height', 'x', 'y', 'dx', 'dy']);

for (const bad of [undefined, null, [], 'state', new Date()]) {
  assert.throws(() => advanceToken(bad), TypeError);
}
const base = { width: 3, height: 3, x: 1, y: 1, dx: 0, dy: 0 };
for (const key of Object.keys(base)) {
  const missing = { ...base };
  delete missing[key];
  assert.throws(() => advanceToken(missing), TypeError);
}
for (const width of [0, 10001, 1.5, NaN, '3']) {
  assert.throws(() => advanceToken({ ...base, width }), TypeError);
}
for (const height of [0, 10001, 2.5, Infinity, null]) {
  assert.throws(() => advanceToken({ ...base, height }), TypeError);
}
for (const x of [-1, 3, 1.2, NaN, '1']) {
  assert.throws(() => advanceToken({ ...base, x }), TypeError);
}
for (const y of [-1, 3, 1.2, Infinity, null]) {
  assert.throws(() => advanceToken({ ...base, y }), TypeError);
}
for (const velocity of [-2, 2, 0.5, NaN, '1', null]) {
  assert.throws(() => advanceToken({ ...base, dx: velocity }), TypeError);
  assert.throws(() => advanceToken({ ...base, dy: velocity }), TypeError);
}

